results.sparql:
PREFIX iso: <http://www.semanticweb.org/mrwit/ontologies/2026/3/ISO29110V2#>
SELECT ?task ?taskID ?taskDesc ?activityName
       (GROUP_CONCAT(DISTINCT ?roleAbbr; separator=", ") AS ?roles)
       (GROUP_CONCAT(DISTINCT ?outName; separator="; ") AS ?outputs)
WHERE {
  { SELECT DISTINCT ?task ?taskDesc WHERE {
      ?task a iso:Task ; iso:hasTaskDescription ?taskDesc .
      ?task iso:hasRole ?role . ?role iso:hasRoleName ?roleName . FILTER(str(?roleName) = "Technical leader")
      FILTER(REGEX(str(?taskDesc), "verify", "i"))
  } }
  OPTIONAL { ?task iso:hasTaskID ?taskID . }
  OPTIONAL { ?task iso:isTaskOf ?a . ?a iso:hasActivityName ?activityName . }
  OPTIONAL { ?task iso:hasRole ?r . ?r iso:hasRoleAbbreviation ?roleAbbr . }
  OPTIONAL { ?task iso:hasOutputWorkProduct ?o . ?o iso:representsWorkProduct ?ow . ?ow iso:hasWorkProductName ?outName . }
}
GROUP BY ?task ?taskID ?taskDesc ?activityName
ORDER BY ?taskID

PREFIX iso: <http://www.semanticweb.org/mrwit/ontologies/2026/3/ISO29110V2#>
SELECT ?producer ?producerID ?producerDesc ?wpName ?stateName
       (GROUP_CONCAT(DISTINCT ?roleAbbr; separator=", ") AS ?roles)
WHERE {
  { SELECT DISTINCT ?owp ?wpName ?stateName ?producer ?producerDesc WHERE {
      ?owp iso:representsWorkProduct ?wp ; iso:hasFinalState ?st . ?wp iso:hasWorkProductName ?wpName . ?st iso:hasWorkProductStateName ?stateName .
      FILTER(str(?wpName) = "Project Plan")
      { ?producer a iso:Task ; iso:hasTaskDescription ?producerDesc ; iso:hasOutputWorkProduct ?owp . } UNION
      { ?producer a iso:BasePractice ; iso:hasBasePracticeDescription ?producerDesc ; iso:hasOutputWorkProduct ?owp . } FILTER(REGEX(str(?producerDesc), "verify", "i"))
  } }
  OPTIONAL { ?producer iso:hasTaskID ?taskID . }
  OPTIONAL { ?producer iso:hasBasePracticeID ?bpID . }
  BIND(COALESCE(?taskID, ?bpID) AS ?producerID)
  OPTIONAL { ?producer iso:hasRole ?r . ?r iso:hasRoleAbbreviation ?roleAbbr . }
}
GROUP BY ?producer ?producerID ?producerDesc ?wpName ?stateName
ORDER BY ?producerID

PREFIX iso: <http://www.semanticweb.org/mrwit/ontologies/2026/3/ISO29110V2#>
SELECT ?bp ?bpID ?bpDesc ?po ?process ?poID ?poDesc
       (GROUP_CONCAT(DISTINCT ?outName; separator="; ") AS ?outputs)
WHERE {
  { SELECT DISTINCT ?bp ?bpDesc ?po ?poDesc WHERE {
      ?bp a iso:BasePractice ; iso:hasBasePracticeDescription ?bpDesc ; iso:hasProcessOutcome ?po .
      ?po iso:hasProcessOutcomeDescription ?poDesc .
      BIND(CONCAT(str(?bpDesc), " ", str(?poDesc)) AS ?text)
      ?bp iso:hasOutputWorkProduct ?fo . ?fo iso:representsWorkProduct ?fw . ?fw iso:hasWorkProductName ?fwName . FILTER(str(?fwName) = "Project Plan")
      FILTER(REGEX(str(?text), "verify", "i"))
  } }
  OPTIONAL { ?bp iso:hasBasePracticeID ?bpID . }
  OPTIONAL { ?po iso:hasProcessOutcomeID ?poID . }
  OPTIONAL { ?proc a iso:Process ; iso:hasBasePractice ?bp . BIND(STRAFTER(str(?proc), "#") AS ?process) }
  OPTIONAL { ?bp iso:hasOutputWorkProduct ?o . ?o iso:representsWorkProduct ?ow . ?ow iso:hasWorkProductName ?outName . }
}
GROUP BY ?bp ?bpID ?bpDesc ?po ?process ?poID ?poDesc
ORDER BY ?bp ?po
